diff --git a/backend/tests/repository.test.ts b/backend/tests/repository.test.ts
index 362f57f..53a6e44 100644
--- a/backend/tests/repository.test.ts
+++ b/backend/tests/repository.test.ts
@@ -17,6 +17,20 @@ it('lists tasks in newest-first order and maps database rows', async () => {
   expect(await repository.list()).toEqual([todo]);
   expect(findMany).toHaveBeenCalledWith({ orderBy: [{ created_at: 'desc' }, { id: 'desc' }] });
 });
+it('filters by priority while keeping newest-first order, and sends no filter otherwise', async () => {
+  const { database, repository } = setup();
+  const findMany = vi.spyOn(database.todo, 'findMany').mockResolvedValue([record]);
+  expect(await repository.list({ priority: 'low' })).toEqual([todo]);
+  expect(await repository.list({})).toEqual([todo]);
+  expect(findMany).toHaveBeenCalledTimes(2);
+  expect(findMany).toHaveBeenNthCalledWith(1, {
+    where: { priority: 'low' },
+    orderBy: [{ created_at: 'desc' }, { id: 'desc' }],
+  });
+  const unfiltered = findMany.mock.calls[1][0];
+  expect(unfiltered).not.toHaveProperty('where');
+  expect(unfiltered).toMatchObject({ orderBy: [{ created_at: 'desc' }, { id: 'desc' }] });
+});
 it('gets a task by ID and handles missing tasks', async () => {
   const { database, repository } = setup();
   const findUnique = vi.spyOn(database.todo, 'findUnique').mockResolvedValueOnce(record).mockResolvedValueOnce(null);
diff --git a/backend/tests/router.test.ts b/backend/tests/router.test.ts
index 4f3ada2..619468e 100644
--- a/backend/tests/router.test.ts
+++ b/backend/tests/router.test.ts
@@ -11,13 +11,29 @@ function setup() {
   app.use('/api/todos', createTodosRouter(repository));
   return { app, repository };
 }
-it('lists tasks from the repository', async () => {
+it('lists tasks from the repository, forwarding the parsed priority filter', async () => {
   const { app, repository } = setup();
   const response = await request(app).get('/api/todos');
   expect(response.status).toBe(200);
   expect(response.body).toEqual([todo]);
   expect(repository.list).toHaveBeenCalledOnce();
+  expect(repository.list).toHaveBeenNthCalledWith(1, {});
+  const filtered = await request(app).get('/api/todos?priority=high');
+  expect(filtered.status).toBe(200);
+  expect(filtered.body).toEqual([todo]);
+  expect(repository.list).toHaveBeenCalledTimes(2);
+  expect(repository.list).toHaveBeenNthCalledWith(2, { priority: 'high' });
 });
+it.each(['priority=urgent', 'priority=HIGH', 'priority=', 'priority=low&priority=high'])(
+  'rejects invalid priority query %s without calling the repository', async (query) => {
+    const { app, repository } = setup();
+    const response = await request(app).get(`/api/todos?${query}`);
+    expect(response.status).toBe(422);
+    expect(Array.isArray(response.body.detail)).toBe(true);
+    expect(response.body.detail.length).toBeGreaterThan(0);
+    expect(repository.list).not.toHaveBeenCalled();
+  },
+);
 it('creates tasks with trimmed input and defaults', async () => {
   const { app, repository } = setup();
   const response = await request(app).post('/api/todos').send({ title: '  Plan the sprint  ', priority: 'high' });
diff --git a/backend/tests/validators.test.ts b/backend/tests/validators.test.ts
index cd1fdb5..6645e4c 100644
--- a/backend/tests/validators.test.ts
+++ b/backend/tests/validators.test.ts
@@ -1,5 +1,5 @@
 import { describe, it, expect } from 'vitest';
-import { createSchema, updateSchema, idSchema, todoSchema } from '../src/features/todos/validators.ts';
+import { createSchema, updateSchema, idSchema, todoSchema, listQuerySchema } from '../src/features/todos/validators.ts';
 import { todo } from './fixture.ts';

 describe('todo validation', () => {
@@ -38,3 +38,17 @@ describe('todo validation', () => {
     expect(todoSchema.safeParse({ ...todo, created_at: 'yesterday' }).success).toBe(false);
   });
 });
+
+describe('list query validation', () => {
+  it('treats priority as optional', () => {
+    const parsed = listQuerySchema.parse({});
+    expect(parsed).toEqual({});
+    expect(parsed).not.toHaveProperty('priority');
+  });
+  it.each(['low', 'medium', 'high'])('accepts priority %s', (priority) => {
+    expect(listQuerySchema.parse({ priority })).toEqual({ priority });
+  });
+  it.each(['urgent', '', 'HIGH', null, ['low', 'high']])('rejects priority %j', (priority) => {
+    expect(listQuerySchema.safeParse({ priority }).success).toBe(false);
+  });
+});
